#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_srcMode;
uniform float amzp_pattern;
uniform float amzp_kStyle;
uniform float amzp_beatMotion;
uniform float amzp_tempoSrc;
uniform float amzp_beatSrc;
uniform float amzp_edges;
uniform float amzp_mirrorOn;
uniform float amzp_ledOn;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_segs;
uniform float amzp_tile;
uniform float2 amzp_center;
uniform float amzp_rotate;
uniform float amzp_spinSpeed;
uniform float amzp_swirl;
uniform float amzp_bulge;
uniform float amzp_srcZoom;
uniform float2 amzp_srcOffset;
uniform float amzp_srcSpin;
uniform float amzp_tunnelSpeed;
uniform float amzp_foldSteps;
uniform float amzp_foldShift;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
layout(color) uniform half4 amzp_colC;
layout(color) uniform half4 amzp_bgCol;
uniform float amzp_patScale;
uniform float amzp_lineW;
uniform float amzp_glow;
uniform float amzp_patSpeed;
uniform float amzp_bpm;
uniform float amzp_beatOffset;
uniform float amzp_stepAngle;
uniform float amzp_stepEase;
uniform float amzp_bloomStr;
uniform float amzp_bloomW;
uniform float amzp_colorStep;
uniform float amzp_strobeAmt;
uniform float amzp_hitDecay;
uniform float amzp_ledSize;
uniform float amzp_ledGap;
uniform float amzp_audioLevel;
uniform float amzp_bass;
uniform float amzp_mid;
uniform float amzp_high;
uniform float amzp_audio_level;
uniform float amzp_threshold;
uniform float amzp_curve;
uniform float amzp_beatRush;
uniform float amzp_brightPunch;
uniform float amzp_hueShift;
uniform float amzp_saturation;
uniform float amzp_brightness;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 rot(float2 v, float a) { float c = cos(a), s = sin(a); return float2(c * v.x - s * v.y, s * v.x + c * v.y); }
    float hsh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
    float2 reflEdge(float2 q, float2 P0, float2 P1, float2 I, inout bool moved) {
        float2 e = P1 - P0;
        float2 n = normalize(float2(-e.y, e.x));
        if (dot(I - P0, n) < 0.0) n = -n;
        float d = dot(q - P0, n);
        if (d < 0.0) { q -= 2.0 * d * n; moved = true; }
        return q;
    }
    float2 foldTri(float2 q, float2 A, float2 B, float2 C) {
        float2 I = (A + B + C) / 3.0;
        for (int i = 0; i < 16; i++) {
            bool mv = false;
            q = reflEdge(q, A, B, I, mv);
            q = reflEdge(q, B, C, I, mv);
            q = reflEdge(q, C, A, I, mv);
            if (!mv) break;
        }
        return q;
    }
    float3 hueTurn(float3 c, float deg) {
        float a = radians(deg), cs = cos(a), sn = sin(a);
        float3 k = float3(0.57735);
        return c * cs + cross(k, c) * sn + k * dot(k, c) * (1.0 - cs);
    }
    float3 pal(float v) {
        v = fract(v) * 3.0;
        if (v < 1.0) return mix(amzp_colA.rgb, amzp_colB.rgb, v);
        if (v < 2.0) return mix(amzp_colB.rgb, amzp_colC.rgb, v - 1.0);
        return mix(amzp_colC.rgb, amzp_colA.rgb, v - 2.0);
    }
    float edgeCoord(float x) {
        if (int(amzp_edges) == 0) return 1.0 - abs(mod(x, 2.0) - 1.0);
        if (int(amzp_edges) == 1) return fract(x);
        return clamp(x, 0.0, 1.0);
    }
    float4 sampleLayer(float2 sp, float2 L) {
        float2 uv = float2(sp.x / L.x + 0.5, 0.5 - sp.y / L.y);
        if (int(amzp_edges) == 3 && (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)) return float4(0.0);
        uv = float2(edgeCoord(uv.x), edgeCoord(uv.y));
        return amzTexture(0, l2s(uv));
    }
    float neon(float d) {
        float w = max(amzp_lineW, 0.2);
        return clamp(1.0 - smoothstep(0.5 * w - 0.75, 0.5 * w + 0.75, d), 0.0, 1.0) + amzp_glow * 0.6 * exp(-max(d - 0.5 * w, 0.0) / (w * 2.5));
    }
    float4 genPat(float2 sp, float t, float cs) {
        float sc = max(amzp_patScale, 1.0);
        float v = 0.0, a = 0.0;
        if (int(amzp_pattern) == 3) {
            float2 u = sp / sc;
            float pv = sin(u.x + t * 2.0) + sin(u.y * 1.3 - t * 1.4) + sin((u.x + u.y) * 0.7 + t) + sin(length(u) * 1.5 - t * 2.0);
            return float4(pal(pv * 0.125 + 0.5 + cs), 1.0);
        }
        if (int(amzp_pattern) == 0) {
            float u = sp.x / sc + t;
            a = neon(abs(fract(u) - 0.5) * sc);
            v = floor(u + 0.5) * 0.37;
        } else if (int(amzp_pattern) == 1) {
            float u = length(sp) / sc - t;
            a = neon(abs(fract(u) - 0.5) * sc);
            v = floor(u + 0.5) * 0.29;
        } else if (int(amzp_pattern) == 2) {
            float r = length(sp) / sc, an = atan(sp.y, sp.x);
            float u = r - 0.35 * cos(an * 6.0 + t * 2.0) - t;
            a = neon(abs(fract(u) - 0.5) * sc);
            v = floor(u + 0.5) * 0.31 + an * 0.05;
        } else if (int(amzp_pattern) == 4) {
            float2 cell = floor(sp / sc + 0.5);
            float2 g = (sp / sc - cell) * sc;
            float rr = max(amzp_lineW, 0.2) * (1.2 + 0.8 * sin(t * 6.2831853 + hsh(cell) * 6.2831853));
            a = neon(max(length(g) - rr, 0.0) + 0.5 * max(amzp_lineW, 0.2));
            v = hsh(cell) + t * 0.1;
        } else {
            float r = length(sp), an = atan(sp.y, sp.x);
            float rays = max(floor(1200.0 / sc), 3.0);
            float u = an / 6.2831853 * rays + t;
            a = neon(abs(fract(u) - 0.5) * 6.2831853 / rays * r);
            v = floor(u + 0.5) * 0.41 + r / sc * 0.02;
            a *= smoothstep(0.0, sc * 0.5, r);
        }
        a = clamp(a, 0.0, 1.0);
        return float4(pal(v + cs) * a, a);
    }
    float2 kaleido(float2 p, float N, float T, float swirlA, float minS) {
        float rn = length(p) / (0.5 * minS);
        p *= 1.0 - clamp(amzp_bulge, -0.95, 0.95) * exp(-rn * rn * 2.0);
        p = rot(p, swirlA * length(p) / (0.5 * minS));
        float seg = 6.2831853 / N;
        float s = max(amzp_tile, 1.0);
        float2 q;
        if (int(amzp_kStyle) == 0 || int(amzp_kStyle) == 4) {
            float r = length(p);
            float a = mod(atan(p.y, p.x), seg);
            if ((amzp_mirrorOn>0.5)) a = abs(a - 0.5 * seg);
            if (int(amzp_kStyle) == 0) q = float2(cos(a), sin(a)) * r;
            else {
                float span = (amzp_mirrorOn>0.5) ? 0.5 * seg : seg;
                float v = log(max(r, 0.5) / s) * N / 6.2831853 - T * amzp_tunnelSpeed;
                q = float2((a / span - 0.5) * s, (abs(fract(v * 0.5) * 2.0 - 1.0) - 0.5) * s);
            }
        } else if (int(amzp_kStyle) == 2) {
            float2 m = abs(mod(p / s + 1.0, 2.0) - 1.0);
            if (m.y > m.x) m = m.yx;
            q = (m - float2(2.0 / 3.0, 1.0 / 3.0)) * s;
        } else if (int(amzp_kStyle) == 1 || int(amzp_kStyle) == 3) {
            float2 a1 = float2(1.5, 0.8660254) * s, a2 = float2(0.0, 1.7320508) * s;
            float det = a1.x * a2.y - a1.y * a2.x;
            float2 c = float2(p.x * a2.y - p.y * a2.x, a1.x * p.y - a1.y * p.x) / det;
            float2 qq = p - a1 * floor(c.x + 0.5) - a2 * floor(c.y + 0.5);
            float2 A = float2(0.0), B = float2(s, 0.0), C = float2(0.5 * s, 0.8660254 * s);
            qq = foldTri(qq, A, B, C);
            float2 G = (A + B + C) / 3.0;
            if (int(amzp_kStyle) == 3) {
                float2 nn = float2(-0.5, 0.8660254);
                float d = dot(qq, nn);
                if (d > 0.0) qq -= 2.0 * d * nn;
                G = float2(1.75 * s, 0.4330127 * s) / 3.0;
            }
            q = qq - G;
        } else {
            q = p;
            float2 sh = float2(amzp_foldShift * s * 0.5);
            for (int i = 0; i < 20; i++) {
                if (float(i) >= amzp_foldSteps) break;
                q = abs(q) - sh;
                q = rot(q, seg);
            }
        }
        q = rot(q, -radians(amzp_srcSpin * T));
        return q / max(amzp_srcZoom, 0.01) + amzp_srcOffset;
    }
    void amzRender() {
        float2 L = layer;
        float minS = min(L.x, L.y);
        float lv = int(amzp_beatSrc) == 1 ? amzp_bass : (int(amzp_beatSrc) == 2 ? amzp_mid : (int(amzp_beatSrc) == 3 ? amzp_high : amzp_audioLevel));
        float th = clamp(amzp_threshold, 0.0, 0.95);
        float drive = pow(clamp((lv - th) / (1.0 - th), 0.0, 1.0), max(amzp_curve, 0.05));
        float T = amzp_progress * 10.0 + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0);
        float P = int(amzp_tempoSrc) == 1 ? amzp_audio_level * amzp_beatRush + amzp_beatOffset : T * amzp_bpm / 60.0 + amzp_beatOffset;
        float bk = floor(P), bf = P - bk;
        float tau = bk + smoothstep(0.0, max(amzp_stepEase, 0.001), bf);
        float hit = int(amzp_tempoSrc) == 0 ? exp(-bf * amzp_hitDecay) : drive;
        bool mStep = int(amzp_beatMotion) == 1 || int(amzp_beatMotion) == 5;
        bool mBloom = int(amzp_beatMotion) == 2 || int(amzp_beatMotion) == 5;
        bool mColor = int(amzp_beatMotion) == 3 || int(amzp_beatMotion) == 5;
        bool mStrobe = int(amzp_beatMotion) == 4 || int(amzp_beatMotion) == 5;
        float N = max(floor(amzp_segs + 0.5), 1.0);
        float ang = radians(amzp_rotate + amzp_spinSpeed * T + (mStep ? amzp_stepAngle * tau : 0.0));
        float swirlA = radians(amzp_swirl);
        float pt = T * amzp_patSpeed + (mStep ? tau * 0.25 : 0.0);
        float cs = mColor ? amzp_colorStep * tau : 0.0;
        float2 p0 = float2(amzLayerNorm().x - 0.5, 0.5 - amzLayerNorm().y) * L - amzp_center;
        float qn = max(floor(amzp_quality + 0.5), 1.0);
        float cell = max(amzp_ledSize, 1.0);
        float2 ledLocal = float2(0.0);
        if ((amzp_ledOn>0.5)) {
            float2 cc = floor(p0 / cell) + 0.5;
            ledLocal = p0 / cell - cc;
            p0 = cc * cell;
            qn = 1.0;
        }
        float4 acc = float4(0.0);
        float cnt = 0.0;
        for (int iy = 0; iy < 4; iy++) {
            if (float(iy) >= qn) break;
            for (int ix = 0; ix < 4; ix++) {
                if (float(ix) >= qn) break;
                float2 o = (amzp_ledOn>0.5) ? float2(0.0) : (float2(float(ix), float(iy)) + 0.5) / qn - 0.5;
                float2 p = rot(p0 + o, -ang);
                float2 sp = kaleido(p, N, T, swirlA, minS);
                float4 c;
                if (int(amzp_srcMode) == 0) {
                    c = genPat(sp, pt, cs);
                    c += float4(amzp_bgCol.rgb * amzp_bgCol.a, amzp_bgCol.a) * (1.0 - c.a);
                } else c = sampleLayer(sp, L);
                acc += c;
                cnt += 1.0;
            }
        }
        float4 c = acc / max(cnt, 1.0);
        float3 rgb = c.a > 1e-4 ? c.rgb / c.a : float3(0.0);
        float al = c.a;
        if (mColor && int(amzp_srcMode) == 1) rgb = hueTurn(rgb, amzp_colorStep * tau * 360.0);
        if (mBloom) {
            float rr = length(p0) / (0.5 * minS);
            float bw = max(amzp_bloomW, 0.01);
            float ring = exp(-pow((rr - bf * 1.6) / bw, 2.0)) * (1.0 - bf);
            float3 bc = int(amzp_srcMode) == 0 ? pal(cs + 0.5) : float3(1.0);
            rgb += bc * ring * amzp_bloomStr;
            al = max(al, clamp(ring * amzp_bloomStr, 0.0, 1.0));
        }
        float hs = amzp_hueShift;
        if (abs(hs) > 0.01) rgb = hueTurn(rgb, hs);
        float lw = dot(rgb, float3(0.2126, 0.7152, 0.0722));
        rgb = mix(float3(lw), rgb, amzp_saturation) * amzp_brightness * (1.0 + amzp_brightPunch * drive);
        if (mStrobe) rgb *= max(1.0 + amzp_strobeAmt * (1.6 * hit - 0.6), 0.0);
        if ((amzp_ledOn>0.5)) {
            float rad = 0.5 * (1.0 - clamp(amzp_ledGap, 0.0, 0.9));
            float dd = length(ledLocal);
            float px = 1.0 / cell;
            float dotM = 1.0 - smoothstep(rad - px, rad + px, dd);
            rgb *= dotM * (1.0 + 0.35 * (1.0 - dd / max(rad, 1e-3)));
            al *= max(dotM, 0.0);
        }
        amzOutput = float4(clamp(rgb, 0.0, 1.0) * al, al);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
